static int emit(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 peak[]={-14336,12288,0,-14336,14336,12288};static const p2d89_q14 range[]={-16384,12288,-8192,0,-4096,6144,2048,-8192,6144,0,10240,-4096,16384,12288};static const p2d89_q14 conifer[]={0,-14336,8192,0,4096,0,11264,10240,-11264,10240,-4096,0,-8192,0};if(id==P2D89_SHAPE_MOUNTAIN_PEAK)return p2d89_i_poly(peak,3U,0,p);if(id==P2D89_SHAPE_MOUNTAIN_RANGE)return p2d89_i_poly(range,7U,0,p);if(id==P2D89_SHAPE_HILL){if(!p2d89_i_move(p,-14336,8192))return 0;return p2d89_i_cubic(p,-8192,-8192,8192,-8192,14336,8192);}if(id==P2D89_SHAPE_VALLEY){if(!p2d89_i_move(p,-14336,-8192))return 0;return p2d89_i_cubic(p,-8192,8192,8192,8192,14336,-8192);}if(id==P2D89_SHAPE_TREE_DECIDUOUS)return tree(0,-2048,p);if(id==P2D89_SHAPE_TREE_CONIFER){if(!p2d89_i_poly(conifer,7U,1,p))return 0;return l(0,10240,0,16384,p);}if(id==P2D89_SHAPE_FOREST_CLUSTER){if(!tree(-7168,0,p))return 0;if(!tree(7168,0,p))return 0;return tree(0,-7168,p);}if(id==P2D89_SHAPE_WATER_WAVE){if(!wave(-4096,p))return 0;return wave(4096,p);}if(id==P2D89_SHAPE_RIVER_MEANDER){if(!p2d89_i_move(p,-14336,-12288))return 0;if(!p2d89_i_cubic(p,8192,-12288,-8192,0,0,0))return 0;return p2d89_i_cubic(p,8192,0,-8192,12288,14336,12288);}if(id==P2D89_SHAPE_CONTOUR_LOOP){if(!p2d89_i_move(p,14336,0))return 0;if(!p2d89_i_cubic(p,12288,11264,4096,14336,-4096,12288))return 0;if(!p2d89_i_cubic(p,-14336,10240,-16384,-4096,-10240,-10240))return 0;if(!p2d89_i_cubic(p,-2048,-16384,10240,-12288,14336,0))return 0;return p2d89_i_close(p);}return 0;}
